"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"

/** An index: hairline-separated rows. The one you point at reverses out of ink and steps forward. */
function Rows({ className, ...props }: React.ComponentProps<"ul">) {
  return <ul data-slot="rows" className={cn("db-rows", className)} {...props} />
}

type RowProps = Omit<React.ComponentProps<"li">, "onClick"> & {
  /** Makes the row a link. Without href (or asChild) it is a plain row that doesn't react. */
  href?: string
  /** Render your own link (Next's Link, say) inside the row with the row's look. */
  asChild?: boolean
  /** Pins a state for documentation ("hover"); set on the link. */
  "data-force"?: string
  /** Passed to the link. */
  onClick?: React.MouseEventHandler<HTMLElement>
}

/**
 * One row. Give it the parts (RowTitle, RowKind, RowMeta). A row that opens
 * something draws a → on hover; the ink comes in from the side your hand came in
 * and leaves toward the side it goes.
 */
function Row({ href, asChild = false, className, children, onClick, "data-force": force, ...props }: RowProps) {
  const Comp = asChild ? Slot : href !== undefined ? "a" : "div"
  const edge = (e: React.PointerEvent<HTMLElement>) => {
    const r = e.currentTarget.getBoundingClientRect()
    e.currentTarget.dataset.edge = e.clientY < r.top + r.height / 2 ? "top" : "bottom"
  }
  return (
    <li data-slot="rows-item" {...props}>
      <Comp
        data-slot="rows-row"
        data-force={force}
        className={cn("db-rows-link", className)}
        {...(href !== undefined ? { href } : {})}
        onClick={onClick}
        onPointerEnter={edge}
        onPointerLeave={edge}
      >
        {children}
      </Comp>
    </li>
  )
}

function RowTitle({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="rows-title" className={cn("db-rows-title", className)} {...props} />
}

function RowKind({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="rows-kind" className={cn("db-rows-kind", className)} {...props} />
}

/** The quiet fact at the end: a year, a count. */
function RowMeta({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="rows-meta" className={cn("db-rows-meta", className)} {...props} />
}

export { Rows, Row, RowTitle, RowKind, RowMeta, type RowProps }

@layer components {
  /* ── db-rows ── an index; the row you point at steps forward.
     Only a row that opens something (an a or a button) reverses and shows the arrow. */
  .db-rows { list-style: none; margin: 0; padding: 0; border-top: var(--db-hairline) solid var(--db-rule); }
  .db-rows > li { border-bottom: var(--db-hairline) solid var(--db-rule); }
  .db-rows-link {
    position: relative; isolation: isolate;
    display: grid; grid-template-columns: minmax(0, 1fr); grid-auto-flow: column; grid-auto-columns: auto;
    align-items: baseline; column-gap: var(--db-space-6);
    padding: var(--db-space-4) 0; color: inherit; text-decoration: none; --step: 8px;
  }
  :is([dir="rtl"], [dir="rtl"] *) .db-rows-link { --step: -8px; }
  .db-rows-title { font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 300; color: var(--db-ink); transition: translate var(--db-moderato) var(--db-exhale); }
  .db-rows-kind { color: var(--db-graphite); }
  .db-rows-meta { min-inline-size: 4ch; color: var(--db-pencil); font-variant-numeric: tabular-nums; text-align: end; }
  .db-rows-link:is(a[href], button)::after {
    content: "→" / ""; inline-size: 1.2em; justify-self: end; color: var(--db-ink); opacity: 0; translate: calc(-1 * var(--step)) 0;
    transition: opacity var(--db-allegro), translate var(--db-moderato) var(--db-exhale), color var(--db-allegro);
  }
  :is([dir="rtl"], [dir="rtl"] *) .db-rows-link:is(a[href], button)::after { content: "←" / ""; }
  /* The row you point at reverses: ink wipes in from the side your hand came in, the heaviest emphasis there is. */
  .db-rows-link:is(a[href], button)::before {
    content: ""; position: absolute; inset: 0 calc(-1 * var(--db-space-3)); z-index: -1;
    background: var(--db-ink); scale: 1 0; transform-origin: 50% 0;
    transition: scale var(--db-moderato) var(--db-exhale);
  }
  .db-rows-link[data-edge="bottom"]::before { transform-origin: 50% 100%; }
  .db-rows-link:is(a[href], button) > * { transition: color var(--db-allegro), translate var(--db-moderato) var(--db-exhale), opacity var(--db-allegro); }
  .db-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"])::before { scale: 1 1; }
  .db-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"]) > * { color: var(--db-paper); }
  .db-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"])::after { color: var(--db-paper); opacity: 1; translate: 0 0; }
  .db-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"]) .db-rows-title { translate: var(--step) 0; }
  .db-rows-link:focus-visible { outline-offset: 4px; }
}
